CREATE OR REPLACE FUNCTION public.finance_sku_payout_count_summary(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n declare\n  v_start date := coalesce(p_start, current_date - 30);\n  v_end date := coalesce(p_end, current_date);\n  v_user_id uuid;\n  v_tenant_id uuid;\n  v_marketplace text := lower(trim(coalesce(p_marketplace, '')));\n  v_result jsonb;\nbegin\n  begin\n    v_user_id := nullif(\n      coalesce(\n        auth.uid()::text,\n        (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')\n      ),\n      ''\n    )::uuid;\n  exception when others then\n    v_user_id := null;\n  end;\n\n  select coalesce(u.tenant_id, current_setting('app.current_tenant_id', true)::uuid)\n    into v_tenant_id\n  from public.users u\n  where u.user_id = v_user_id\n  limit 1;\n\n  if v_tenant_id is null then\n    v_tenant_id := coalesce(current_setting('app.current_tenant_id', true)::uuid, (select tenant_id from public.users limit 1));\n  end if;\n\n  if v_tenant_id is null then return '{"ok":false,"error":"tenant_id required"}'::jsonb; end if;\n\n  with valid_orders as (\n    select\n      o.tenant_id,\n      o.marketplace_order_id,\n      o.marketplace_account_id,\n      o.marketplace,\n      o.external_order_id,\n      o.order_sn,\n      o.order_status,\n      o.status,\n      coalesce(nullif(o.external_order_id, ''), nullif(o.order_sn, ''), o.marketplace_order_id::text) as order_key,\n      (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta') as order_ts_wib,\n      (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date as order_date_wib\n    from public.marketplace_orders o\n    where o.tenant_id = v_tenant_id\n      and (v_marketplace = '' or lower(coalesce(o.marketplace, '')) = v_marketplace)\n      and (p_account_id is null or o.marketplace_account_id = p_account_id)\n      and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date >= v_start\n      and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date <= v_end\n  ),\n  finance_by_order as (\n    select\n      coalesce(nullif(order_id, ''), marketplace_order_id::text, 'no_order_id_' || md5(random()::text)) as order_key,\n      marketplace_account_id,\n      marketplace,\n      max(settlement_status) as settlement_status,\n      sum(coalesce(payout_amount, net_settlement, 0)) as payout_total\n    from public.marketplace_finance_reports\n    where tenant_id = v_tenant_id\n      and (v_marketplace = '' or lower(coalesce(marketplace, '')) = v_marketplace)\n      and (p_account_id is null or marketplace_account_id = p_account_id)\n      and coalesce(settlement_date, period_start) >= v_start\n      and coalesce(settlement_date, period_start) <= v_end\n    group by 1, 2, 3\n  ),\n  detail as (\n    select\n      vo.marketplace_account_id,\n      vo.marketplace,\n      vo.order_key,\n      vo.order_status,\n      vo.order_date_wib,\n      oi.marketplace_sku_id,\n      oi.quantity as qty,\n      coalesce(nullif(oi.marketplace_seller_sku, ''), nullif(oi.seller_sku, '')) as marketplace_seller_sku,\n      coalesce(nullif(oi.mapped_local_sku, ''), nullif(oi.local_sku, ''), 'Unmapped') as local_sku,\n      coalesce(nullif(oi.product_name, ''), nullif(oi.marketplace_product_name, ''), nullif(oi.local_product_name, '')) as product_name,\n      coalesce(nullif(oi.variant_name, ''), nullif(oi.marketplace_variant_name, ''), nullif(oi.variation_name, '')) as variant_name,\n      greatest(\n        coalesce(oi.gross_amount, 0),\n        coalesce(oi.paid_amount, 0),\n        coalesce(oi.unit_gross_amount, 0) * greatest(coalesce(nullif(oi.quantity, 0), nullif(oi.qty, 0), 1), 1)\n      ) as gross_line\n    from valid_orders vo\n    join public.marketplace_order_items oi\n      on oi.tenant_id = vo.tenant_id\n      and oi.marketplace_order_id = vo.marketplace_order_id\n    where oi.marketplace_sku_id is not null\n      and nullif(trim(oi.marketplace_sku_id), '') is not null\n      and nullif(trim(oi.marketplace_sku_id), '-') is not null\n      and nullif(trim(coalesce(oi.marketplace_seller_sku, oi.seller_sku, '')), '') is not null\n      and nullif(trim(coalesce(oi.marketplace_seller_sku, oi.seller_sku, '')), '-') is not null\n  ),\n  hpp_sku as (\n    select tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, '')) as marketplace_sku_id,\n           max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\n           max(nullif(local_sku, '')) as mapped_local_sku\n    from public.marketplace_variant_hpp_mappings\n    where coalesce(is_active, true) is true and nullif(marketplace_sku_id, '') is not null\n      and tenant_id = v_tenant_id\n    group by tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, ''))\n  ),\n  hpp_seller as (\n    select tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, '')) as marketplace_seller_sku,\n           max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\n           max(nullif(local_sku, '')) as mapped_local_sku\n    from public.marketplace_variant_hpp_mappings\n    where coalesce(is_active, true) is true and nullif(marketplace_seller_sku, '') is not null\n      and tenant_id = v_tenant_id\n    group by tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, ''))\n  ),\n  hpp_local as (\n    select tenant_id, marketplace_account_id, lower(nullif(local_sku, '')) as local_sku,\n           max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\n           max(nullif(local_sku, '')) as mapped_local_sku\n    from public.marketplace_variant_hpp_mappings\n    where coalesce(is_active, true) is true and nullif(local_sku, '') is not null\n      and tenant_id = v_tenant_id\n    group by tenant_id, marketplace_account_id, lower(nullif(local_sku, ''))\n  ),\n  enriched as (\n    select\n      d.marketplace_account_id,\n      d.marketplace,\n      d.order_key,\n      d.order_status,\n      d.order_date_wib,\n      d.marketplace_sku_id,\n      d.qty,\n      d.marketplace_seller_sku,\n      d.local_sku,\n      d.product_name,\n      d.variant_name,\n      d.gross_line,\n      fbo.payout_total as order_payout,\n      fbo.settlement_status,\n      sum(nullif(d.gross_line, 0)) over (partition by d.marketplace_account_id, d.order_key) as gross_order_scope,\n      sum(d.qty) over (partition by d.marketplace_account_id, d.order_key) as qty_order_scope,\n      coalesce(hs.hpp, hsel.hpp, hl.hpp, 0)::numeric as unit_hpp,\n      coalesce(hs.mapped_local_sku, hsel.mapped_local_sku, hl.mapped_local_sku, d.local_sku) as live_local_sku\n    from detail d\n    left join finance_by_order fbo\n      on fbo.marketplace_account_id = d.marketplace_account_id\n      and fbo.order_key = d.order_key\n    left join hpp_sku hs on hs.marketplace_account_id = d.marketplace_account_id and hs.marketplace_sku_id = lower(nullif(d.marketplace_sku_id, ''))\n    left join hpp_seller hsel on hsel.marketplace_account_id = d.marketplace_account_id and hsel.marketplace_seller_sku = lower(nullif(d.marketplace_seller_sku, ''))\n    left join hpp_local hl on hl.marketplace_account_id = d.marketplace_account_id and hl.local_sku = lower(nullif(d.local_sku, ''))\n  ),\n  allocated as (\n    select\n      *,\n      case\n        when coalesce(order_payout, 0) = 0 then 0\n        when coalesce(gross_order_scope, 0) > 0 and gross_line > 0 then order_payout * gross_line / gross_order_scope\n        when coalesce(qty_order_scope, 0) > 0 then order_payout * qty / qty_order_scope\n        else order_payout\n      end as payout_allocated\n    from enriched\n  ),\n  calculated as (\n    select\n      a.*,\n      upper(coalesce(a.order_status, '')) as order_status_upper,\n      case\n        when upper(coalesce(a.order_status, '')) like '%CANCEL%'\n          or upper(coalesce(a.order_status, '')) like '%REFUND%'\n          or upper(coalesce(a.order_status, '')) like '%RETURN%' then 'Cancel/Refund/Return'\n        when coalesce(a.order_payout, 0) = 0 then 'Belum Payout'\n        when a.payout_allocated < 0 then 'Payout Minus'\n        else coalesce(nullif(a.settlement_status, ''), 'Settled')\n      end as payout_status_clean\n    from allocated a\n  ),\n  flagged as (\n    select\n      c.*,\n      (\n        c.order_status_upper like '%CANCEL%'\n        or c.order_status_upper like '%REFUND%'\n        or c.order_status_upper like '%RETURN%'\n        or upper(c.payout_status_clean) like '%CANCEL%'\n        or upper(c.payout_status_clean) like '%REFUND%'\n        or upper(c.payout_status_clean) like '%RETURN%'\n      ) as is_cancel_refund_return\n    from calculated c\n  ),\n  grouped as (\n    select\n      marketplace_account_id,\n      marketplace,\n      coalesce(nullif(marketplace_sku_id, ''), '-') as marketplace_sku_id,\n      coalesce(nullif(marketplace_seller_sku, ''), '-') as marketplace_seller_sku,\n      coalesce(nullif(local_sku, ''), '-') as local_sku,\n      max(product_name) as product_name,\n      max(variant_name) as variant_name,\n      max(unit_hpp) as unit_hpp,\n\n      count(*) filter (\n        where not is_cancel_refund_return\n          and coalesce(payout_allocated, 0) <> 0\n      )::int as paid_rows,\n\n      count(*) filter (\n        where not is_cancel_refund_return\n          and coalesce(payout_allocated, 0) = 0\n          and payout_status_clean = 'Belum Payout'\n      )::int as unpaid_rows,\n\n      coalesce(sum(qty) filter (\n        where not is_cancel_refund_return\n          and coalesce(payout_allocated, 0) <> 0\n      ), 0)::numeric as paid_qty,\n\n      coalesce(sum(qty) filter (\n        where not is_cancel_refund_return\n          and coalesce(payout_allocated, 0) = 0\n          and payout_status_clean = 'Belum Payout'\n      ), 0)::numeric as unpaid_qty,\n\n      coalesce(sum(gross_line) filter (\n        where not is_cancel_refund_return\n          and coalesce(payout_allocated, 0) <> 0\n      ), 0)::numeric as paid_gross_total,\n\n      coalesce(sum(gross_line) filter (\n        where not is_cancel_refund_return\n          and coalesce(payout_allocated, 0) = 0\n          and payout_status_clean = 'Belum Payout'\n      ), 0)::numeric as unpaid_gross_total,\n\n      coalesce(sum(payout_allocated) filter (\n        where not is_cancel_refund_return\n          and coalesce(payout_allocated, 0) <> 0\n      ), 0)::numeric as paid_payout_total,\n\n      count(*)::int as all_rows,\n      coalesce(sum(qty), 0)::numeric as all_qty,\n      coalesce(sum(qty * unit_hpp), 0)::numeric as hpp_total\n    from flagged\n    group by 1, 2, 3, 4, 5\n  )\n  select jsonb_build_object(\n    'ok', true,\n    'version', 'finance_sku_payout_count_summary_2026_07_06_v6_clean_skus',\n    'start', v_start,\n    'end', v_end,\n    'rows', coalesce(jsonb_agg(jsonb_build_object(\n      'marketplace_account_id', marketplace_account_id,\n      'marketplace', marketplace,\n      'marketplace_sku', marketplace_seller_sku,\n      'marketplace_sku_id', marketplace_sku_id,\n      'marketplace_seller_sku', marketplace_seller_sku,\n      'local_sku', local_sku,\n      'product_name', product_name,\n      'variant_name', variant_name,\n      'unit_hpp', unit_hpp,\n      'hpp_total', hpp_total,\n\n      'paid_rows', paid_rows,\n      'unpaid_rows', unpaid_rows,\n      'paid_qty', paid_qty,\n      'unpaid_qty', unpaid_qty,\n\n      'settled_qty', paid_qty,\n      'qty_unpaid', unpaid_qty,\n      'paid_total', paid_rows,\n      'unpaid_total', unpaid_rows,\n\n      'paid_gross_total', paid_gross_total,\n      'unpaid_gross_total', unpaid_gross_total,\n      'paid_payout_total', paid_payout_total,\n\n      'all_rows', all_rows,\n      'all_qty', all_qty\n    ) order by all_qty desc, product_name, variant_name), '[]'::jsonb)\n  )\n  into v_result\n  from grouped;\n\n  return coalesce(v_result, jsonb_build_object(\n    'ok', true,\n    'version', 'finance_sku_payout_count_summary_2026_07_06_v6_clean_skus',\n    'start', v_start,\n    'end', v_end,\n    'rows', '[]'::jsonb\n  ));\nend;\n$function$\n
CREATE OR REPLACE FUNCTION public.finance_sku_order_details_core_v3(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_marketplace_sku text DEFAULT NULL::text, p_local_sku text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_payout_filter text DEFAULT 'all'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_claims jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);\n  v_tenant_id uuid;\n  v_role text;\n  v_start date := coalesce(p_start, date_trunc('month', timezone('Asia/Jakarta', now()))::date);\n  v_end date := coalesce(p_end, timezone('Asia/Jakarta', now())::date);\n  v_start_ts timestamptz;\n  v_end_ts timestamptz;\n  v_marketplace text;\n  v_account_id uuid := p_account_id;\n  v_marketplace_sku text := lower(nullif(trim(coalesce(p_marketplace_sku, '')), ''));\n  v_local_sku text := lower(nullif(trim(coalesce(p_local_sku, '')), ''));\n  v_search text := lower(nullif(trim(coalesce(p_search, '')), ''));\n  v_filter text := lower(trim(coalesce(p_payout_filter, 'all')));\n  v_page integer := greatest(coalesce(p_page, 1), 1);\n  v_page_size integer := least(greatest(coalesce(p_page_size, 20), 1), 25);\n  v_offset integer;\n  v_detail_mode boolean;\nbegin\n  perform set_config('work_mem', '64MB', true);\n\n  select\n    coalesce(\n      case\n        when (v_claims->>'tenant_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'\n        then (v_claims->>'tenant_id')::uuid\n        else null::uuid\n      end,\n      (select u.tenant_id from public.users u where u.user_id = auth.uid() limit 1)\n    ),\n    coalesce(nullif(v_claims->>'role', ''), '')\n  into v_tenant_id, v_role;\n\n  v_start_ts := (v_start::timestamp at time zone 'Asia/Jakarta');\n  v_end_ts := ((v_end + 1)::timestamp at time zone 'Asia/Jakarta');\n  v_offset := (v_page - 1) * v_page_size;\n  v_filter := case\n    when v_filter in ('settled', 'released', 'release', 'payout', 'paid payout', 'sudah payout') then 'paid'\n    when v_filter in ('pending', 'belum payout', 'no payout', 'missing payout') then 'unpaid'\n    when v_filter = '' then 'all'\n    else v_filter\n  end;\n  v_marketplace := case\n    when lower(regexp_replace(coalesce(p_marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%shopee%' then 'shopee'\n    when lower(regexp_replace(coalesce(p_marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%tiktok%' then 'tiktok'\n    else null\n  end;\n  v_detail_mode := v_marketplace_sku is not null\n    or v_local_sku is not null\n    or v_search is not null;\n\n  if v_role <> 'service_role' and v_tenant_id is null then\n    return jsonb_build_object(\n      'rows', '[]'::jsonb,\n      'page', v_page,\n      'page_size', v_page_size,\n      'total', 0,\n      'total_count', 0,\n      'total_pages', 1,\n      'source', 'finance_sku_order_details_fast_mtd'\n    );\n  end if;\n\n  if v_detail_mode and v_marketplace_sku = 'missing_or_adjustment' then\n    return (\n      with finance_adjustments as (\n        select\n          tenant_id,\n          marketplace_account_id,\n          marketplace,\n          coalesce(nullif(order_id, ''), 'ADJ-' || md5(random()::text)) as order_key,\n          gross_amount,\n          payout_amount,\n          net_settlement,\n          settlement_date,\n          period_start\n        from public.marketplace_finance_reports fr\n        where tenant_id = v_tenant_id\n          and (v_marketplace is null or lower(coalesce(marketplace, '')) like '%' || v_marketplace || '%')\n          and (v_account_id is null or marketplace_account_id = v_account_id)\n          and coalesce(settlement_date, period_start) >= v_start\n          and coalesce(settlement_date, period_start) <= v_end\n          and not exists (\n            select 1 from public.marketplace_orders o\n            where o.tenant_id = fr.tenant_id\n              and coalesce(nullif(o.external_order_id, ''), nullif(o.order_sn, ''), o.marketplace_order_id::text) = coalesce(nullif(fr.order_id, ''), fr.marketplace_order_id::text)\n          )\n      ),\n      paged as (\n        select *\n        from finance_adjustments\n        order by coalesce(settlement_date, period_start) desc, order_key\n        offset v_offset\n        limit v_page_size\n      )\n      select jsonb_build_object(\n        'rows', coalesce(jsonb_agg(jsonb_build_object(\n          'source', 'finance_sku_order_details_fast_mtd_detail',\n          'order', order_key,\n          'order_id', order_key,\n          'order_sn', order_key,\n          'marketplace_order_id', order_key,\n          'marketplace_order_item_id', order_key,\n          'resi', '-',\n          'tracking_number', '-',\n          'order_date', coalesce(settlement_date, period_start),\n          'order_created_at', coalesce(settlement_date, period_start),\n          'marketplace', marketplace,\n          'marketplace_account_id', marketplace_account_id,\n          'local_sku', 'Unmapped',\n          'sku', 'missing_or_adjustment',\n          'marketplace_sku_id', 'missing_or_adjustment',\n          'marketplace_sku', 'missing_or_adjustment',\n          'marketplace_seller_sku', 'missing_or_adjustment',\n          'product_name', 'Platform Adjustment / Missing Order',\n          'variant_name', 'N/A',\n          'marketplace_variation_name', 'N/A',\n          'qty', 1,\n          'quantity', 1,\n          'gross', coalesce(gross_amount, 0),\n          'gross_amount', coalesce(gross_amount, 0),\n          'gross_total', coalesce(gross_amount, 0),\n          'gross_per_item', coalesce(gross_amount, 0),\n          'payout', coalesce(payout_amount, net_settlement, 0),\n          'payout_amount', coalesce(payout_amount, net_settlement, 0),\n          'payout_per_item', coalesce(payout_amount, net_settlement, 0),\n          'hpp', 0,\n          'hpp_total', 0,\n          'hpp_per_item', 0,\n          'unit_hpp', 0,\n          'hpp_status', 'HPP belum mapping',\n          'target_margin_percent', 0,\n          'finance_status', 'SETTLED',\n          'payout_status', 'SETTLED'\n        ) order by coalesce(settlement_date, period_start) desc, order_key), '[]'::jsonb),\n        'page', v_page,\n        'page_size', v_page_size,\n        'total', (select count(*) from finance_adjustments),\n        'total_count', (select count(*) from finance_adjustments),\n        'total_pages', greatest(1, ceil((select count(*) from finance_adjustments)::numeric / v_page_size)::integer),\n        'source', 'finance_sku_order_details_fast_mtd'\n      )\n    );\n  end if;\n\n  if v_detail_mode then\n    return (\n      with order_base as (\n        select *\n        from (\n          select\n            o.marketplace_order_id,\n            o.tenant_id,\n            o.marketplace_account_id,\n            o.order_created_at,\n            timezone('Asia/Jakarta', o.order_created_at)::date as order_date,\n            coalesce(nullif(o.order_id::text, ''), nullif(o.order_sn::text, ''), nullif(o.external_order_id::text, ''), o.marketplace_order_id::text) as order_key,\n            coalesce(nullif(o.order_sn::text, ''), nullif(o.external_order_id::text, ''), nullif(o.order_id::text, '')) as order_sn,\n            coalesce(nullif(o.tracking_number, ''), nullif(o.label_code, ''), nullif(o.package_id, '')) as tracking_number,\n            lower(concat_ws(' ', o.order_status, o.status, o.payment_status, o.fulfillment_status, o.order_status_label)) as status_text,\n            coalesce(nullif(o.gross_amount, 0), nullif(o.total_amount, 0), nullif(o.paid_amount, 0), 0)::numeric as order_gross,\n            case\n              when lower(regexp_replace(coalesce(o.marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%shopee%' then 'shopee'\n              when lower(regexp_replace(coalesce(o.marketplace, ''), '[^a-z0-9]+', '', 'g')) like '%tiktok%' then 'tiktok'\n              else lower(regexp_replace(coalesce(o.marketplace, 'unknown'), '[^a-z0-9]+', '', 'g'))\n            end as marketplace_group\n          from public.marketplace_orders o\n          where coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) >= v_start_ts\n      and coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) < v_end_ts\n            and (v_role = 'service_role' or o.tenant_id = v_tenant_id)\n            and (v_account_id is null or o.marketplace_account_id = v_account_id)\n        ) o\n        where (v_marketplace is null or v_marketplace = '' or o.marketplace_group = public._finance_marketplace_norm_20260624(v_marketplace))\n          and o.status_text not like '%cancel%'\n          and o.status_text not like '%batal%'\n          and o.status_text not like '%unpaid%'\n          and o.status_text not like '%in_cancel%'\n          and o.status_text not like '%refund%'\n          and o.status_text not like '%return%'\n      ),\n      finance_by_order as (\n        select\n          ob.marketplace_order_id,\n          coalesce(sum(coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0)), 0)::numeric as payout,\n          coalesce(sum(coalesce(fr.gross_amount, fr.gross_sales, 0)), 0)::numeric as finance_gross,\n          coalesce(sum(coalesce(fr.platform_fee, 0)), 0)::numeric as platform_fee,\n          coalesce(sum(coalesce(fr.commission_fee, 0)), 0)::numeric as commission_fee,\n          coalesce(sum(coalesce(fr.affiliate_fee, 0)), 0)::numeric as affiliate_fee,\n          coalesce(sum(coalesce(fr.shipping_fee, 0)), 0)::numeric as shipping_fee,\n          coalesce(sum(coalesce(fr.discount_amount, 0)), 0)::numeric as discount_amount,\n          coalesce(sum(coalesce(fr.voucher_amount, 0)), 0)::numeric as voucher_amount,\n          coalesce(sum(coalesce(fr.refund_amount, 0)), 0)::numeric as refund_amount,\n          coalesce(sum(coalesce(fr.adjustment_amount, 0)), 0)::numeric as adjustment_amount\n        from order_base ob\n        join \n        (\n          select tenant_id, marketplace_account_id, marketplace, order_id, marketplace_order_id, gross_amount, gross_sales, payout_amount, received_amount, net_settlement, platform_fee, commission_fee, affiliate_fee, shipping_fee, discount_amount, voucher_amount, refund_amount, adjustment_amount\n          from public.marketplace_finance_reports\n          where lower(coalesce(marketplace, '')) not in ('tiktok', 'tiktok_shop')\n\n          union all\n\n          select tenant_id, marketplace_account_id, marketplace, coalesce(nullif(order_id, ''), nullif(order_sn, ''), nullif(external_order_id, '')) as order_id, marketplace_order_id, gross_amount, gross_amount as gross_sales, received_amount as payout_amount, received_amount, net_settlement, null as platform_fee, null as commission_fee, null as affiliate_fee, null as shipping_fee, null as discount_amount, null as voucher_amount, null as refund_amount, null as adjustment_amount\n          from public.marketplace_finance_items\n          where lower(coalesce(marketplace, '')) in ('tiktok', 'tiktok_shop')\n        ) fr\n          on fr.tenant_id = ob.tenant_id\n         and fr.marketplace_account_id = ob.marketplace_account_id\n         and fr.order_id = ob.order_key\n        group by ob.marketplace_order_id\n      ),\n      line_base as (\n        select\n          ob.*,\n          oi.marketplace_order_item_id,\n          coalesce(nullif(oi.marketplace_sku_id, ''), nullif(oi.remote_sku_id, '')) as marketplace_sku_id,\n          coalesce(nullif(oi.marketplace_sku, ''), nullif(oi.marketplace_sku_id, ''), nullif(oi.remote_sku_id, '')) as marketplace_sku,\n          coalesce(nullif(oi.marketplace_seller_sku, ''), nullif(oi.seller_sku, '')) as marketplace_seller_sku,\n          coalesce(nullif(oi.local_sku, ''), nullif(oi.mapped_local_sku, '')) as local_sku,\n          coalesce(nullif(oi.marketplace_product_name, ''), nullif(oi.product_name, ''), nullif(oi.local_product_name, '')) as product_name,\n          coalesce(nullif(oi.marketplace_variant_name, ''), nullif(oi.variant_name, ''), nullif(oi.variation_name, '')) as variant_name,\n          greatest(coalesce(nullif(oi.qty, 0), nullif(oi.quantity, 0), 1), 1)::numeric as qty,\n          coalesce(\n            nullif(oi.gross_amount, 0),\n            nullif(oi.paid_amount, 0),\n            nullif(oi.unit_gross_amount, 0) * greatest(coalesce(nullif(oi.qty, 0), nullif(oi.quantity, 0), 1), 1),\n            0\n          )::numeric as line_gross\n        from order_base ob\n        join public.marketplace_order_items oi\n          on oi.tenant_id = ob.tenant_id\n         and oi.marketplace_order_id = ob.marketplace_order_id\n        where (v_marketplace_sku is null or v_marketplace_sku in (\n            lower(coalesce(oi.marketplace_sku_id, '')),\n            lower(coalesce(oi.marketplace_sku, '')),\n            lower(coalesce(oi.remote_sku_id, '')),\n            lower(coalesce(oi.marketplace_seller_sku, '')),\n            lower(coalesce(oi.seller_sku, ''))\n          ))\n          and (v_local_sku is null or v_local_sku = lower(coalesce(oi.local_sku, oi.mapped_local_sku, '')))\n          and (v_search is null or lower(concat_ws(' ', ob.order_key, ob.order_sn, ob.tracking_number, oi.marketplace_sku_id, oi.marketplace_sku, oi.marketplace_seller_sku, oi.seller_sku, oi.local_sku, oi.mapped_local_sku, oi.marketplace_product_name, oi.product_name, oi.marketplace_variant_name, oi.variant_name)) like '%' || v_search || '%')\n      ),\n      line_calc as (\n        select lb.*, sum(lb.line_gross) over (partition by lb.marketplace_order_id) as order_line_gross\n        from line_base lb\n      ),\n      enriched_base as (\n        select\n          lc.*,\n          coalesce(f.payout, 0)::numeric as order_payout,\n          (coalesce(f.payout, 0) <> 0) as has_payout\n        from line_calc lc\n        left join finance_by_order f on f.marketplace_order_id = lc.marketplace_order_id\n      ),\n      filtered as (\n        select *\n        from enriched_base\n        where (v_filter = 'all' or (v_filter = 'paid' and has_payout) or (v_filter = 'unpaid' and not has_payout))\n      ),\n      counted as (\n        select filtered.*, count(*) over ()::integer as total_count\n        from filtered\n      ),\n      paged as (\n        select *\n        from counted\n        order by order_created_at desc, order_key\n        offset v_offset\n        limit v_page_size\n      ),\n      hpp_sku as (\n        select tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, '')) as marketplace_sku_id,\n               max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\n               max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin\n        from public.marketplace_variant_hpp_mappings\n        where coalesce(is_active, true) is true and nullif(marketplace_sku_id, '') is not null\n          and (v_role = 'service_role' or tenant_id = v_tenant_id)\n        group by tenant_id, marketplace_account_id, lower(nullif(marketplace_sku_id, ''))\n      ),\n      hpp_seller as (\n        select tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, '')) as marketplace_seller_sku,\n               max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\n               max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin\n        from public.marketplace_variant_hpp_mappings\n        where coalesce(is_active, true) is true and nullif(marketplace_seller_sku, '') is not null\n          and (v_role = 'service_role' or tenant_id = v_tenant_id)\n        group by tenant_id, marketplace_account_id, lower(nullif(marketplace_seller_sku, ''))\n      ),\n      hpp_local as (\n        select tenant_id, marketplace_account_id, lower(nullif(local_sku, '')) as local_sku,\n               max(coalesce(hpp, hpp_amount, hpp_per_item, 0))::numeric as hpp,\n               max(coalesce(target_margin_percent, target_margin, 0))::numeric as target_margin\n        from public.marketplace_variant_hpp_mappings\n        where coalesce(is_active, true) is true and nullif(local_sku, '') is not null\n          and (v_role = 'service_role' or tenant_id = v_tenant_id)\n        group by tenant_id, marketplace_account_id, lower(nullif(local_sku, ''))\n      ),\n      paged_enriched as (\n        select\n          p.*,\n          coalesce(hs.hpp, hsel.hpp, hl.hpp, 0)::numeric as unit_hpp,\n          coalesce(hs.target_margin, hsel.target_margin, hl.target_margin, 0)::numeric as target_margin\n        from paged p\n        left join public.marketplace_variant_hpp_mappings hpp\n          on hpp.tenant_id = p.tenant_id\n         and (\n           (p.marketplace_group = 'shopee' and hpp.marketplace = 'shopee')\n           or (p.marketplace_group = 'tiktok_shop' and hpp.marketplace = 'tiktok_shop')\n         )\n         and coalesce(nullif(p.marketplace_sku_id, ''), p.marketplace_product_id) = coalesce(nullif(hpp.marketplace_variant_id, ''), hpp.marketplace_product_id)\n      )\n      select jsonb_build_object(\n        'rows', coalesce(jsonb_agg(jsonb_build_object(\n          'source', 'finance_sku_order_details_fast_mtd_detail',\n          'order', order_key,\n          'order_id', order_key,\n          'order_sn', order_sn,\n          'marketplace_order_id', marketplace_order_id,\n          'marketplace_order_item_id', marketplace_order_item_id,\n          'resi', tracking_number,\n          'tracking_number', tracking_number,\n          'order_date', order_created_at,\n          'order_created_at', order_created_at,\n          'marketplace', marketplace_group,\n          'marketplace_account_id', marketplace_account_id,\n          'local_sku', coalesce(nullif(local_sku, ''), '-'),\n          'sku', coalesce(nullif(local_sku, ''), nullif(marketplace_sku_id, ''), nullif(marketplace_seller_sku, ''), '-'),\n          'marketplace_sku_id', marketplace_sku_id,\n          'marketplace_sku', marketplace_sku,\n          'marketplace_seller_sku', marketplace_seller_sku,\n          'product_name', product_name,\n          'variant_name', variant_name,\n          'marketplace_variation_name', variant_name,\n          'qty', qty,\n          'quantity', qty,\n          'gross', line_gross,\n          'gross_amount', line_gross,\n          'gross_total', line_gross,\n          'gross_per_item', case when qty > 0 then line_gross / qty else 0 end,\n          'payout', case when has_payout and order_line_gross > 0 then order_payout * (line_gross / order_line_gross) else 0 end,\n          'payout_amount', case when has_payout and order_line_gross > 0 then order_payout * (line_gross / order_line_gross) else 0 end,\n          'payout_per_item', case when has_payout and order_line_gross > 0 and qty > 0 then (order_payout * (line_gross / order_line_gross)) / qty else 0 end,\n          'hpp', unit_hpp * qty,\n          'hpp_total', unit_hpp * qty,\n          'hpp_per_item', unit_hpp,\n          'unit_hpp', unit_hpp,\n          'hpp_status', case when unit_hpp > 0 then 'HPP mapping' else 'HPP belum mapping' end,\n          'target_margin_percent', target_margin,\n          'finance_status', case when has_payout then 'SETTLED' else 'PENDING_PAYOUT' end,\n          'payout_status', case when has_payout then 'SETTLED' else 'PENDING_PAYOUT' end\n        ) order by order_created_at desc, order_key), '[]'::jsonb),\n        'page', v_page,\n        'page_size', v_page_size,\n        'total', coalesce(max(total_count), 0),\n        'total_count', coalesce(max(total_count), 0),\n        'total_pages', greatest(1, ceil(coalesce(max(total_count), 0)::numeric / v_page_size)::integer),\n        'source', 'finance_sku_order_details_fast_mtd'\n      )\n      from paged_enriched\n    );\n  end if;\n\n  return jsonb_build_object('ok', true);\nend;\n$function$\n
CREATE OR REPLACE FUNCTION public.finance_sku_order_details(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_marketplace_sku text DEFAULT NULL::text, p_local_sku text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_payout_filter text DEFAULT 'all'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\n SET statement_timeout TO '25s'\nAS $function$\r\n\r\ndeclare\r\n\r\n  v_claims jsonb := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);\r\n\r\n  v_user_id uuid;\r\n\r\n  v_tenant_id uuid;\r\n\r\n  v_role text := coalesce(nullif(v_claims->>'role',''), '');\r\n\r\n  v_start date := coalesce(p_start, date_trunc('month', now() at time zone 'Asia/Jakarta')::date);\r\n\r\n  v_end date := coalesce(p_end, (now() at time zone 'Asia/Jakarta')::date);\r\n\r\n  v_start_ts timestamptz := (coalesce(p_start, date_trunc('month', now() at time zone 'Asia/Jakarta')::date)::timestamp at time zone 'Asia/Jakarta');\r\n\r\n  v_end_ts timestamptz := ((coalesce(p_end, (now() at time zone 'Asia/Jakarta')::date) + 1)::timestamp at time zone 'Asia/Jakarta');\r\n\r\n\r\n\r\n  v_marketplace text := public._finance_marketplace_norm_20260624(p_marketplace);\r\n\r\n  v_account_id uuid := p_account_id;\r\n\r\n  v_msku text := lower(nullif(trim(coalesce(p_marketplace_sku,'')), ''));\r\n\r\n  v_lsku text := lower(nullif(trim(coalesce(p_local_sku,'')), ''));\r\n\r\n  v_search text := lower(nullif(trim(coalesce(p_search,'')), ''));\r\n\r\n  v_filter text := lower(trim(coalesce(p_payout_filter,'all')));\r\n\r\n  v_page integer := greatest(coalesce(p_page,1),1);\r\n\r\n  v_page_size integer := least(greatest(coalesce(p_page_size,20),1),25);\r\n\r\n  v_offset integer := (greatest(coalesce(p_page,1),1)-1) * least(greatest(coalesce(p_page_size,20),1),25);\r\n\r\n  v_detail boolean;\r\n\r\n  v_core jsonb;\r\n\r\n  v_core_rows integer := 0;\r\n\r\n  v_core_has_weak_fields boolean := false;\r\n\r\n  v_result jsonb;\r\n\r\nbegin\r\n\r\n  v_detail := v_msku is not null or v_lsku is not null or v_search is not null;\r\n\r\n\r\n\r\n  if not v_detail then\r\n\r\n    return public.finance_sku_order_details_group_20260625(\r\n\r\n      p_start,p_end,p_marketplace,p_account_id,p_marketplace_sku,p_local_sku,p_search,p_payout_filter,p_page,p_page_size\r\n\r\n    );\r\n\r\n  end if;\r\n\r\n\r\n\r\n  v_core := public.finance_sku_order_details_core_v3(\r\n\r\n    p_start,p_end,p_marketplace,p_account_id,p_marketplace_sku,p_local_sku,p_search,p_payout_filter,p_page,p_page_size\r\n\r\n  );\r\n\r\n\r\n\r\n  v_core_rows := coalesce(jsonb_array_length(coalesce(v_core->'rows','[]'::jsonb)),0);\r\n\r\n\r\n\r\n  select exists (\r\n\r\n    select 1\r\n\r\n    from jsonb_array_elements(coalesce(v_core->'rows','[]'::jsonb)) r\r\n\r\n    where coalesce(r->>'gross_sales', r->>'gross_total', r->>'gross_amount', '') = ''\r\n\r\n       or coalesce(r->>'product_name', r->>'product', r->>'title', '') = ''\r\n\r\n  )\r\n\r\n  into v_core_has_weak_fields;\r\n\r\n\r\n\r\n  -- Kalau core detail sehat, pakai core. Kalau core ada rows tapi field penting kosong, paksa enriched fallback.\r\n\r\n  if v_core_rows > 0 and not v_core_has_weak_fields then\r\n\r\n    return jsonb_set(\r\n\r\n      v_core,\r\n\r\n      '{source}',\r\n\r\n      to_jsonb((coalesce(v_core->>'source','finance_sku_order_details_core_v3') || '+core_hit_strong')::text),\r\n\r\n      true\r\n\r\n    );\r\n\r\n  end if;\r\n\r\n\r\n\r\n  begin\r\n\r\n    v_user_id := nullif(coalesce(auth.uid()::text, v_claims->>'sub'), '')::uuid;\r\n\r\n  exception when others then\r\n\r\n    v_user_id := null;\r\n\r\n  end;\r\n\r\n\r\n\r\n  select u.tenant_id\r\n\r\n    into v_tenant_id\r\n\r\n  from public.users u\r\n\r\n  where u.user_id = v_user_id\r\n\r\n  limit 1;\r\n\r\n\r\n\r\n  if v_role <> 'service_role' and v_tenant_id is null then\r\n\r\n    return jsonb_build_object(\r\n\r\n      'rows','[]'::jsonb,\r\n\r\n      'page',v_page,\r\n\r\n      'page_size',v_page_size,\r\n\r\n      'total',0,\r\n\r\n      'total_count',0,\r\n\r\n      'total_pages',1,\r\n\r\n      'source','finance_sku_order_details_detail_enriched_no_tenant_20260625'\r\n\r\n    );\r\n\r\n  end if;\r\n\r\n\r\n\r\n  with order_base as (\r\n\r\n    select\r\n\r\n      o.marketplace_order_id,\r\n\r\n      o.tenant_id,\r\n\r\n      o.marketplace_account_id,\r\n\r\n      public._finance_marketplace_norm_20260624(o.marketplace) as marketplace,\r\n\r\n      o.order_created_at,\r\n\r\n      coalesce(nullif(o.order_id::text,''), nullif(o.order_sn::text,''), nullif(o.external_order_id::text,''), o.marketplace_order_id::text) as order_key,\r\n\r\n      coalesce(nullif(o.order_sn::text,''), nullif(o.external_order_id::text,''), nullif(o.order_id::text,'')) as order_sn,\r\n\r\n      coalesce(nullif(o.tracking_number,''), nullif(o.label_code,''), nullif(o.package_id,'')) as tracking_number,\r\n\r\n      lower(concat_ws(' ', o.order_status, o.status, o.payment_status, o.fulfillment_status, o.order_status_label)) as status_text,\r\n\r\n      coalesce(nullif(o.order_status,''), nullif(o.status,''), nullif(o.order_status_label,''), nullif(o.fulfillment_status,''), 'UNKNOWN') as order_status_raw,\r\n\r\n      coalesce(nullif(o.payment_status,''), '') as payment_status_raw,\r\n\r\n      coalesce(nullif(o.fulfillment_status,''), '') as fulfillment_status_raw,\r\n\r\n      coalesce(nullif(o.gross_amount,0), nullif(o.total_amount,0), nullif(o.paid_amount,0), 0)::numeric as order_gross\r\n\r\n    from public.marketplace_orders o\r\n\r\n    where o.order_created_at >= v_start_ts\r\n\r\n      and o.order_created_at < v_end_ts\r\n\r\n      and (v_role = 'service_role' or o.tenant_id = v_tenant_id)\r\n\r\n      and (v_account_id is null or o.marketplace_account_id = v_account_id)\r\n\r\n      and (v_marketplace is null or public._finance_marketplace_norm_20260624(o.marketplace) = v_marketplace)\r\n\r\n      and lower(concat_ws(' ', o.order_status, o.status, o.payment_status, o.fulfillment_status, o.order_status_label)) not like '%cancel%'\r\n\r\n      and lower(concat_ws(' ', o.order_status, o.status, o.payment_status, o.fulfillment_status, o.order_status_label)) not like '%batal%'\r\n\r\n      and lower(concat_ws(' ', o.order_status, o.status, o.payment_status, o.fulfillment_status, o.order_status_label)) not like '%unpaid%'\r\n\r\n  ),\r\n\r\n  finance_by_order as (\r\n\r\n    select\r\n\r\n      fi.tenant_id,\r\n\r\n      fi.marketplace_account_id,\r\n\r\n      coalesce(nullif(fi.order_id,''), nullif(fi.order_sn,''), nullif(fi.external_order_id,''), nullif(fi.remote_order_id,'')) as order_key,\r\n\r\n      coalesce(sum(coalesce(fi.received_amount, fi.net_settlement, 0)),0)::numeric as payout,\r\n\r\n      coalesce(sum(coalesce(fi.gross_amount,0)),0)::numeric as finance_gross\r\n\r\n    from public.marketplace_finance_items fi\r\n\r\n    where (v_role = 'service_role' or fi.tenant_id = v_tenant_id)\r\n\r\n      and (v_account_id is null or fi.marketplace_account_id = v_account_id)\r\n\r\n      and (v_marketplace is null or public._finance_marketplace_norm_20260624(fi.marketplace) = v_marketplace)\r\n\r\n    group by fi.tenant_id, fi.marketplace_account_id,\r\n\r\n      coalesce(nullif(fi.order_id,''), nullif(fi.order_sn,''), nullif(fi.external_order_id,''), nullif(fi.remote_order_id,''))\r\n\r\n  ),\r\n\r\n  line_base_raw as (\r\n\r\n    select\r\n\r\n      ob.*,\r\n\r\n      oi.marketplace_order_item_id,\r\n\r\n      coalesce(nullif(oi.marketplace_sku_id,''), nullif(oi.remote_sku_id,''), nullif(oi.marketplace_sku,''), nullif(oi.marketplace_seller_sku,''), nullif(oi.seller_sku,''), nullif(oi.local_sku,''), nullif(oi.mapped_local_sku,'')) as marketplace_sku,\r\n\r\n      coalesce(nullif(oi.marketplace_seller_sku,''), nullif(oi.seller_sku,''), nullif(oi.marketplace_sku,''), nullif(oi.local_sku,'')) as marketplace_seller_sku,\r\n\r\n      coalesce(nullif(oi.local_sku,''), nullif(oi.mapped_local_sku,''), nullif(oi.seller_sku,''), nullif(oi.marketplace_seller_sku,''), nullif(oi.marketplace_sku,'')) as local_sku,\r\n\r\n      coalesce(nullif(oi.marketplace_product_name,''), nullif(oi.product_name,''), nullif(oi.local_product_name,''), nullif(to_jsonb(oi)->>'item_name',''), nullif(to_jsonb(oi)->>'title',''), nullif(oi.marketplace_sku,''), nullif(oi.local_sku,''), '-') as product_name,\r\n\r\n      coalesce(nullif(oi.marketplace_variant_name,''), nullif(oi.variant_name,''), nullif(oi.variation_name,''), nullif(to_jsonb(oi)->>'model_name',''), '-') as variant_name,\r\n\r\n      greatest(coalesce(nullif(oi.qty,0), nullif(oi.quantity,0), 1),1)::numeric as qty,\r\n\r\n      coalesce(\r\n\r\n        nullif(oi.gross_amount,0),\r\n\r\n        nullif(oi.paid_amount,0),\r\n\r\n        nullif(oi.unit_gross_amount,0) * greatest(coalesce(nullif(oi.qty,0), nullif(oi.quantity,0), 1),1),\r\n\r\n        nullif(ob.order_gross,0),\r\n\r\n        0\r\n\r\n      )::numeric as line_gross,\r\n\r\n      lower(concat_ws(' ',\r\n\r\n        ob.order_key, ob.order_sn, ob.tracking_number,\r\n\r\n        oi.marketplace_sku_id, oi.remote_sku_id, oi.marketplace_sku,\r\n\r\n        oi.marketplace_seller_sku, oi.seller_sku,\r\n\r\n        oi.local_sku, oi.mapped_local_sku,\r\n\r\n        oi.marketplace_product_name, oi.product_name, oi.local_product_name,\r\n\r\n        to_jsonb(oi)->>'item_name', to_jsonb(oi)->>'title',\r\n\r\n        oi.marketplace_variant_name, oi.variant_name, oi.variation_name, to_jsonb(oi)->>'model_name'\r\n\r\n      )) as search_blob\r\n\r\n    from order_base ob\r\n\r\n    join public.marketplace_order_items oi\r\n\r\n      on oi.tenant_id = ob.tenant_id\r\n\r\n     and oi.marketplace_order_id = ob.marketplace_order_id\r\n\r\n  ),\r\n\r\n  line_base as (\r\n\r\n    select *\r\n\r\n    from line_base_raw\r\n\r\n    where\r\n\r\n      (v_msku is null or search_blob like '%' || v_msku || '%')\r\n\r\n      or (v_lsku is not null and search_blob like '%' || v_lsku || '%')\r\n\r\n      or (v_search is not null and search_blob like '%' || v_search || '%')\r\n\r\n  ),\r\n\r\n  line_calc as (\r\n\r\n    select\r\n\r\n      lb.*,\r\n\r\n      sum(lb.line_gross) over (partition by lb.marketplace_order_id) as order_line_gross\r\n\r\n    from line_base lb\r\n\r\n  ),\r\n\r\n  enriched as (\r\n\r\n    select\r\n\r\n      lc.*,\r\n\r\n      coalesce(f.payout,0)::numeric as order_payout,\r\n\r\n      case\r\n\r\n        when coalesce(lc.order_line_gross,0) > 0\r\n\r\n        then coalesce(f.payout,0)::numeric * (coalesce(lc.line_gross,0)::numeric / lc.order_line_gross)\r\n\r\n        else coalesce(f.payout,0)::numeric\r\n\r\n      end as line_payout\r\n\r\n    from line_calc lc\r\n\r\n    left join finance_by_order f\r\n\r\n      on f.tenant_id = lc.tenant_id\r\n\r\n     and f.marketplace_account_id = lc.marketplace_account_id\r\n\r\n     and f.order_key in (lc.order_key, lc.order_sn)\r\n\r\n  ),\r\n\r\n  filtered as (\r\n\r\n    select *\r\n\r\n    from enriched\r\n\r\n    where v_filter in ('all','')\r\n\r\n       or (v_filter in ('paid','settled','payout','sudah payout') and coalesce(order_payout,0) > 0)\r\n\r\n       or (v_filter in ('unpaid','pending','belum payout','no payout') and coalesce(order_payout,0) <= 0)\r\n\r\n  ),\r\n\r\n  dedup as (\r\n\r\n    select distinct on (order_key, marketplace_sku, local_sku, marketplace_order_item_id)\r\n\r\n      *\r\n\r\n    from filtered\r\n\r\n    order by order_key, marketplace_sku, local_sku, marketplace_order_item_id, order_created_at desc\r\n\r\n  ),\r\n\r\n  counted as (\r\n\r\n    select *, count(*) over ()::integer as total_count\r\n\r\n    from dedup\r\n\r\n  ),\r\n\r\n  paged as (\r\n\r\n    select *\r\n\r\n    from counted\r\n\r\n    order by order_created_at desc, order_key, marketplace_order_item_id\r\n\r\n    offset v_offset\r\n\r\n    limit v_page_size\r\n\r\n  )\r\n\r\n  select jsonb_build_object(\r\n\r\n    'rows',\r\n\r\n      coalesce(jsonb_agg(jsonb_build_object(\r\n\r\n        'source','finance_sku_order_details_detail_enriched_when_core_weak_20260625',\r\n\r\n        'order', order_key,\r\n\r\n        'order_id', order_key,\r\n\r\n        'order_sn', order_sn,\r\n\r\n        'marketplace_order_id', marketplace_order_id,\r\n\r\n        'marketplace_order_item_id', marketplace_order_item_id,\r\n\r\n        'resi', tracking_number,\r\n\r\n        'tracking_number', tracking_number,\r\n\r\n        'order_date', order_created_at,\r\n\r\n        'order_created_at', order_created_at,\r\n\r\n        'marketplace', marketplace,\r\n\r\n        'marketplace_account_id', marketplace_account_id,\r\n\r\n        'marketplace_sku', coalesce(nullif(marketplace_sku,''), '-'),\r\n\r\n        'marketplace_seller_sku', coalesce(nullif(marketplace_seller_sku,''), '-'),\r\n\r\n        'local_sku', coalesce(nullif(public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'local_sku',''), '-'),\r\n\r\n        'raw_local_sku', coalesce(nullif(local_sku,''), '-'),\r\n\r\n        'mapping_id', public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'mapping_id',\r\n\r\n        'product_name', coalesce(nullif(product_name,''), coalesce(nullif(marketplace_sku,''), '-')),\r\n\r\n        'variant_name', coalesce(nullif(variant_name,''), '-'),\r\n\r\n        'qty', qty,\r\n\r\n        'quantity', qty,\r\n\r\n        'gross_amount', line_gross,\r\n\r\n        'gross_sales', line_gross,\r\n\r\n        'gross_total', line_gross,\r\n\r\n        'payout_amount', line_payout,\r\n\r\n        'payout_total', line_payout,\r\n\r\n        'received_amount', line_payout,\r\n\r\n        'net_settlement', line_payout,\r\n\r\n        'status', coalesce(nullif(order_status_raw,''), 'UNKNOWN'),\r\n\r\n        'order_status', coalesce(nullif(order_status_raw,''), 'UNKNOWN'),\r\n\r\n        'payment_status', coalesce(nullif(payment_status_raw,''), ''),\r\n\r\n        'fulfillment_status', coalesce(nullif(fulfillment_status_raw,''), ''),\r\n\r\n        'payout_status', case when coalesce(order_payout,0) > 0 then 'SETTLED' else 'PENDING_PAYOUT' end,\r\n\r\n        'hpp', public._finance_num_20260625(public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'hpp'),\r\n\r\n        'hpp_total', public._finance_num_20260625(public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'hpp') * qty,\r\n\r\n        'total_hpp', public._finance_num_20260625(public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'hpp') * qty,\r\n\r\n        'target_margin', public._finance_num_20260625(public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'target_margin'),\r\n\r\n        'profit', line_payout - (public._finance_num_20260625(public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'hpp') * qty),\r\n\r\n        'margin_percent', case when line_gross > 0 then round(((line_payout - (public._finance_num_20260625(public.finance_resolve_variant_mapping_20260625(tenant_id, marketplace_account_id, marketplace_sku, marketplace_seller_sku, local_sku)->>'hpp') * qty)) / line_gross) * 100, 2) else 0 end\r\n\r\n      ) order by order_created_at desc, order_key), '[]'::jsonb),\r\n\r\n    'page', v_page,\r\n\r\n    'page_size', v_page_size,\r\n\r\n    'total', coalesce(max(total_count),0),\r\n\r\n    'total_count', coalesce(max(total_count),0),\r\n\r\n    'total_pages', greatest(ceil(coalesce(max(total_count),0)::numeric / v_page_size)::integer, 1),\r\n\r\n    'source','finance_sku_order_details_detail_enriched_when_core_weak_20260625',\r\n\r\n    'core_source', coalesce(v_core->>'source',''),\r\n\r\n    'core_rows', v_core_rows,\r\n\r\n    'core_has_weak_fields', v_core_has_weak_fields,\r\n\r\n    'debug_params', jsonb_build_object(\r\n\r\n      'marketplace', p_marketplace,\r\n\r\n      'marketplace_sku', p_marketplace_sku,\r\n\r\n      'local_sku', p_local_sku,\r\n\r\n      'search', p_search,\r\n\r\n      'payout_filter', p_payout_filter\r\n\r\n    )\r\n\r\n  )\r\n\r\n  into v_result\r\n\r\n  from paged;\r\n\r\n\r\n\r\n  return coalesce(v_result, jsonb_build_object(\r\n\r\n    'rows','[]'::jsonb,\r\n\r\n    'page',v_page,\r\n\r\n    'page_size',v_page_size,\r\n\r\n    'total',0,\r\n\r\n    'total_count',0,\r\n\r\n    'total_pages',1,\r\n\r\n    'source','finance_sku_order_details_detail_enriched_when_core_weak_20260625_empty',\r\n\r\n    'core_source',coalesce(v_core->>'source',''),\r\n\r\n    'core_rows',v_core_rows,\r\n\r\n    'core_has_weak_fields',v_core_has_weak_fields,\r\n\r\n    'debug_params', jsonb_build_object(\r\n\r\n      'marketplace', p_marketplace,\r\n\r\n      'marketplace_sku', p_marketplace_sku,\r\n\r\n      'local_sku', p_local_sku,\r\n\r\n      'search', p_search,\r\n\r\n      'payout_filter', p_payout_filter\r\n\r\n    )\r\n\r\n  ));\r\n\r\nend;\r\n\r\n$function$\n
CREATE OR REPLACE FUNCTION public.finance_sku_order_line_details(p_start date DEFAULT NULL::date, p_end date DEFAULT NULL::date, p_marketplace text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_marketplace_sku text DEFAULT NULL::text, p_local_sku text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_payout_filter text DEFAULT 'all'::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\n SET statement_timeout TO '25s'\nAS $function$\ndeclare\n  v_tenant_id uuid := public.app_current_tenant_id_or_default();\n  v_start date := coalesce(p_start, date_trunc('month', now() at time zone 'Asia/Jakarta')::date);\n  v_end date := coalesce(p_end, (now() at time zone 'Asia/Jakarta')::date);\n  v_marketplace text := nullif(lower(trim(coalesce(p_marketplace,''))), '');\n  v_filter text := lower(trim(coalesce(p_payout_filter,'all')));\n  v_local_sku text := lower(trim(coalesce(p_local_sku,'')));\n  v_page integer := greatest(1, coalesce(p_page, 1));\n  v_page_size integer := least(100, greatest(1, coalesce(p_page_size, 25)));\n  v_offset integer;\n  v_is_unmapped boolean := false;\n  v_rows jsonb;\n  v_total integer;\nbegin\n  v_offset := (v_page - 1) * v_page_size;\n\n  if v_marketplace in ('all','semua','_all','*','-','semua platform') then\n    v_marketplace := null;\n  end if;\n\n  if v_filter in ('','all','semua','-') then\n    v_filter := 'all';\n  elsif v_filter in ('settled','released','release','payout','paid','sudah payout') then\n    v_filter := 'paid';\n  elsif v_filter in ('pending','unpaid','belum payout','no payout','missing payout') then\n    v_filter := 'unpaid';\n  end if;\n\n  -- Detect UI "unmapped" label -> search for null local_sku in DB\n  if v_local_sku in ('unmapped','not_mapped','tidak_dipetakan','belum dipetakan','belum_dipetakan') then\n    v_is_unmapped := true;\n    v_local_sku := '';\n  end if;\n\n  -- Fast path for unmapped: query marketplace_order_items directly\n  if v_is_unmapped then\n    with base as (\n      select\n        o.tenant_id,\n        o.marketplace,\n        coalesce(nullif(o.order_id::text,''), nullif(o.order_sn,''), o.marketplace_order_id::text) as order_key,\n        o.order_created_at,\n        o.order_status,\n        o.marketplace_account_id,\n        oi.marketplace_order_item_id,\n        oi.marketplace_sku,\n        oi.marketplace_seller_sku,\n        oi.seller_sku,\n        null::text as local_sku,\n        oi.marketplace_product_name,\n        oi.product_name,\n        oi.marketplace_variant_name,\n        oi.variant_name,\n        greatest(1, coalesce(nullif(oi.quantity,0), nullif(oi.qty,0), 1))::integer as qty,\n        coalesce(oi.gross_amount, 0)::numeric as gross_amount,\n        coalesce(oi.unit_gross_amount, 0)::numeric as unit_price,\n        oi.marketplace_product_id,\n        oi.marketplace_sku_id,\n        oi.marketplace_order_id\n      from public.marketplace_order_items oi\n      join public.marketplace_orders o\n        on o.marketplace_order_id = oi.marketplace_order_id\n        and o.tenant_id = oi.tenant_id\n      where oi.tenant_id = v_tenant_id\n        and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date >= v_start\n        and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date <= v_end\n        and (p_account_id is null or o.marketplace_account_id = p_account_id)\n        and (\n          v_marketplace is null\n          or public._finance_marketplace_norm_20260624(o.marketplace)\n             = public._finance_marketplace_norm_20260624(v_marketplace)\n        )\n        -- Exclude cancelled/unpaid/batal/failed/refunded orders\n        and not (lower(coalesce(o.order_status, '')) ~ '(cancel|canceled|cancelled|batal|return|returned|refund|refunded|unpaid|failed|reject|in_cancel)')\n        and not (lower(coalesce(o.payment_status, '')) ~ '(unpaid|failed|cancel|canceled|cancelled|refund|refunded)')\n        -- Exclude UUID fake orders\n        and not (o.order_sn ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\n        and not (coalesce(o.order_id, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\n        -- unmapped: local_sku is null/empty on the item\n        and coalesce(nullif(trim(oi.local_sku),''), nullif(trim(oi.mapped_local_sku),'')) is null\n        -- Filter by p_marketplace_sku and p_search in unmapped path\n        and (\n          p_marketplace_sku is null or p_marketplace_sku = ''\n          or lower(p_marketplace_sku) in (\n             lower(oi.marketplace_sku::text),\n             lower(oi.marketplace_seller_sku::text),\n             lower(oi.seller_sku::text),\n             lower(oi.marketplace_sku_id::text),\n             lower(oi.marketplace_product_id::text)\n          )\n        )\n        and (\n          p_search is null or p_search = ''\n          or o.order_id::text ilike '%' || p_search || '%'\n          or coalesce(oi.marketplace_product_name, oi.product_name, '') ilike '%' || p_search || '%'\n        )\n    ),\n    unmapped_base as (\n      select b.*\n      from base b\n      left join lateral (\n        select m.local_sku\n        from public.marketplace_sku_maps m\n        where m.tenant_id = b.tenant_id\n          and m.marketplace_account_id = b.marketplace_account_id\n          and m.marketplace_product_id = b.marketplace_product_id\n          and m.marketplace_sku_id = b.marketplace_sku_id\n          and coalesce(m.status, 'active') = 'active'\n        limit 1\n      ) m on true\n      where m.local_sku is null\n    ),\n    with_payout as (\n      select\n        u.*,\n        coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0)::numeric as order_payout,\n        (fr.finance_report_id is not null) as has_payout\n      from unmapped_base u\n      left join lateral (\n        select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement\n        from (\n          select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement, 1 as priority\n          from public.marketplace_finance_reports fr\n          where fr.tenant_id = u.tenant_id\n            and fr.marketplace_account_id = u.marketplace_account_id\n            and fr.order_id = u.order_key\n            and coalesce(fr.report_type, '') <> 'statement'\n          union all\n          select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement, 2 as priority\n          from public.marketplace_finance_reports fr\n          where fr.tenant_id = u.tenant_id\n            and fr.marketplace_account_id = u.marketplace_account_id\n            and fr.marketplace_order_id = u.marketplace_order_id\n            and coalesce(fr.report_type, '') <> 'statement'\n        ) fr\n        order by priority\n        limit 1\n      ) fr on true\n    ),\n    filtered as (\n      select *\n      from with_payout\n      where\n        v_filter = 'all'\n        or (v_filter = 'paid' and has_payout)\n        or (v_filter = 'unpaid' and not has_payout)\n    ),\n    counted as (\n      select count(*)::integer as total from filtered\n    ),\n    paged as (\n      select * from filtered\n      order by order_created_at desc, order_key, marketplace_order_item_id\n      limit v_page_size offset v_offset\n    )\n    select\n      coalesce(jsonb_agg(\n        jsonb_build_object(\n          'id', marketplace_order_item_id,\n          'order_id', order_key,\n          'order_sn', order_key,\n          'marketplace', marketplace,\n          'marketplace_name', marketplace,\n          'created_at', order_created_at,\n          'order_status', order_status,\n          'status', order_status,\n          'product_name', coalesce(marketplace_product_name, product_name, '-'),\n          'variant_name', coalesce(marketplace_variant_name, variant_name, '-'),\n          'marketplace_sku', coalesce(marketplace_sku, marketplace_seller_sku, seller_sku, '-'),\n          'local_sku', 'Unmapped',\n          'qty', qty,\n          'quantity', qty,\n          'gross_amount', gross_amount,\n          'unit_price', unit_price,\n          'order_payout', order_payout,\n          'has_payout', has_payout\n        ) order by order_created_at desc, order_key\n      ), '[]'::jsonb),\n      (select coalesce(max(total),0) from counted)\n    into v_rows, v_total\n    from paged;\n\n    return jsonb_build_object(\n      'ok', true,\n      'source', 'unmapped_direct_join',\n      'rows', v_rows,\n      'total', v_total,\n      'page', v_page,\n      'page_size', v_page_size,\n      'total_pages', ceil(v_total::numeric / v_page_size::numeric),\n      'total_count', v_total,\n      'summary_source', 'marketplace_order_items'\n    );\n  end if;\n\n  -- Default mapped logic\n  with base_items as (\n    select\n      i.marketplace_order_item_id,\n      i.marketplace_order_id,\n      o.marketplace,\n      o.marketplace_account_id,\n      coalesce(nullif(o.order_id::text,''), nullif(o.order_sn,''), o.marketplace_order_id::text) as order_key,\n      o.order_created_at,\n      o.order_status,\n      i.marketplace_product_name,\n      i.product_name,\n      i.marketplace_variant_name,\n      i.variant_name,\n      i.marketplace_sku,\n      i.marketplace_seller_sku,\n      i.seller_sku,\n      coalesce(nullif(trim(i.local_sku),''), nullif(trim(i.mapped_local_sku),'')) as local_sku,\n      greatest(1, coalesce(nullif(i.quantity,0), nullif(i.qty,0), 1))::integer as qty,\n      coalesce(i.gross_amount, 0)::numeric as gross_amount,\n      coalesce(i.unit_gross_amount, 0)::numeric as unit_price,\n      i.marketplace_sku_id,\n      i.marketplace_product_id\n    from public.marketplace_order_items i\n    join public.marketplace_orders o\n      on o.marketplace_order_id = i.marketplace_order_id\n      and o.tenant_id = i.tenant_id\n    where i.tenant_id = v_tenant_id\n      and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date >= v_start\n      and (coalesce(o.order_created_at, o.paid_at, o.created_time, o.created_at) at time zone 'Asia/Jakarta')::date <= v_end\n      and (p_account_id is null or o.marketplace_account_id = p_account_id)\n      and (\n        v_marketplace is null\n        or public._finance_marketplace_norm_20260624(o.marketplace)\n           = public._finance_marketplace_norm_20260624(v_marketplace)\n      )\n      -- Exclude cancelled/unpaid/batal/failed/refunded orders\n      and not (lower(coalesce(o.order_status, '')) ~ '(cancel|canceled|cancelled|batal|return|returned|refund|refunded|unpaid|failed|reject|in_cancel)')\n      and not (lower(coalesce(o.payment_status, '')) ~ '(unpaid|failed|cancel|canceled|cancelled|refund|refunded)')\n      -- Exclude UUID fake orders\n      and not (o.order_sn ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\n      and not (coalesce(o.order_id, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\n  ),\n  hpp_resolved as (\n    select\n      b.marketplace_order_item_id,\n      coalesce(\n        b.local_sku,\n        hm_sku.local_sku,\n        hm_sel.local_sku\n      ) as effective_local_sku\n    from base_items b\n    left join lateral (\n      select hm.local_sku\n      from public.marketplace_variant_hpp_mappings hm\n      where hm.tenant_id = v_tenant_id\n        and hm.marketplace_account_id = b.marketplace_account_id\n        and lower(nullif(hm.marketplace_sku_id,'')) = lower(nullif(coalesce(b.marketplace_sku, b.marketplace_seller_sku, b.seller_sku),''))\n        and coalesce(hm.is_active, true) = true\n        and nullif(hm.local_sku,'') is not null\n      order by hm.updated_at desc nulls last\n      limit 1\n    ) hm_sku on true\n    left join lateral (\n      select hm.local_sku\n      from public.marketplace_variant_hpp_mappings hm\n      where hm.tenant_id = v_tenant_id\n        and hm.marketplace_account_id = b.marketplace_account_id\n        and lower(nullif(hm.marketplace_seller_sku,'')) = lower(nullif(coalesce(b.marketplace_seller_sku, b.marketplace_sku),''))\n        and coalesce(hm.is_active, true) = true\n        and nullif(hm.local_sku,'') is not null\n      order by hm.updated_at desc nulls last\n      limit 1\n    ) hm_sel on true\n  ),\n  match_sku as (\n    select b.*, hr.effective_local_sku\n    from base_items b\n    join hpp_resolved hr on hr.marketplace_order_item_id = b.marketplace_order_item_id\n    where\n      (\n        p_marketplace_sku is null or p_marketplace_sku = ''\n        or lower(p_marketplace_sku) in (\n           lower(b.marketplace_sku::text),\n           lower(b.marketplace_seller_sku::text),\n           lower(b.seller_sku::text),\n           lower(b.marketplace_sku_id::text),\n           lower(b.marketplace_product_id::text)\n        )\n      )\n      and (\n        v_local_sku is null or v_local_sku = ''\n        or lower(coalesce(hr.effective_local_sku,'')) = v_local_sku\n      )\n      and (\n        p_search is null or p_search = ''\n        or b.order_key ilike '%' || p_search || '%'\n        or coalesce(b.marketplace_product_name, b.product_name, '') ilike '%' || p_search || '%'\n      )\n  ),\n  with_payout as (\n    select\n      m.*,\n      coalesce(fr.payout_amount, fr.received_amount, fr.net_settlement, 0)::numeric as order_payout,\n      (fr.finance_report_id is not null) as has_payout\n    from match_sku m\n    left join lateral (\n      select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement\n      from (\n        select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement, 1 as priority\n        from public.marketplace_finance_reports fr\n        where fr.tenant_id = v_tenant_id\n          and fr.marketplace_account_id = m.marketplace_account_id\n          and fr.order_id = m.order_key\n          and coalesce(fr.report_type, '') <> 'statement'\n        union all\n        select fr.finance_report_id, fr.payout_amount, fr.received_amount, fr.net_settlement, 2 as priority\n        from public.marketplace_finance_reports fr\n        where fr.tenant_id = v_tenant_id\n          and fr.marketplace_account_id = m.marketplace_account_id\n          and fr.marketplace_order_id = m.marketplace_order_id\n          and coalesce(fr.report_type, '') <> 'statement'\n      ) fr\n      order by priority\n      limit 1\n    ) fr on true\n  ),\n  filtered as (\n    select *\n    from with_payout\n    where\n      v_filter = 'all'\n      or (v_filter = 'paid' and has_payout)\n      or (v_filter = 'unpaid' and not has_payout)\n  ),\n  counted as (\n    select count(*)::integer as total from filtered\n  ),\n  paged as (\n    select * from filtered\n    order by order_created_at desc, order_key, marketplace_order_item_id\n    limit v_page_size offset v_offset\n  )\n  select\n    coalesce(jsonb_agg(\n      jsonb_build_object(\n        'id', marketplace_order_item_id,\n        'order_id', order_key,\n        'order_sn', order_key,\n        'marketplace', marketplace,\n        'marketplace_name', marketplace,\n        'created_at', order_created_at,\n        'order_status', order_status,\n        'status', order_status,\n        'product_name', coalesce(marketplace_product_name, product_name, '-'),\n        'variant_name', coalesce(marketplace_variant_name, variant_name, '-'),\n        'marketplace_sku', coalesce(marketplace_sku, marketplace_seller_sku, seller_sku, marketplace_sku_id::text, marketplace_product_id::text, '-'),\n        'local_sku', effective_local_sku,\n        'qty', qty,\n        'quantity', qty,\n        'gross_amount', gross_amount,\n        'unit_price', unit_price,\n        'order_payout', order_payout,\n        'has_payout', has_payout\n      ) order by order_created_at desc, order_key\n    ), '[]'::jsonb),\n    (select coalesce(max(total),0) from counted)\n  into v_rows, v_total\n  from paged;\n\n  return jsonb_build_object(\n    'ok', true,\n    'source', 'mapped_direct_join_with_hpp',\n    'rows', v_rows,\n    'total', v_total,\n    'page', v_page,\n    'page_size', v_page_size,\n    'total_pages', ceil(v_total::numeric / v_page_size::numeric),\n    'total_count', v_total,\n    'summary_source', 'marketplace_order_items'\n  );\nend;\n$function$\n
